// LineGankerPlan::update — ganker.rs:39~62. 반환값 없음. 결과는 self.chats 와 self.phase 로만 나온다.
// 인라인된 것: Position::as_index, Option::unwrap/is_some/is_none/or,
//   AbstractGameWithCache::tower(simulation.rs:1822), EntityType::is_tower2(entity.rs:1308),
//   TowerType::is_second_tower(tower.rs:99), map_regions::is_top_side(map_regions.rs:21),
//   Ord::clamp, Vec::push. 그래서 calls 에는 안 보인다.

fn update(&mut self, _version, _rnd, player, data, goal_data, _ps, _debug) {
  // ── L43 ────────────────────────────────────────────────
  let team = player.info.team;                 // +0x930, bounds-check: team < 2 아니면 panic_bounds_check
  let pos  = player.info.position as usize;    // +0x9c0 (Position::as_index, 0..4)
  let champ = data.cache.player_champion[team][pos];   // 480 + team*40 + pos*8
  if champ.is_null() { unwrap_failed(); }      // Option::unwrap — None 이면 패닉

  // ── L44 ────────────────────────────────────────────────
  let maxhp = champ.stat_cached.hp;            // +0x628
  if maxhp == 0 { panic_const_div_by_zero(); }
  let hp_ratio = champ.hp * 100 / maxhp;       // +0x670 * 100 / +0x628  (정수 나눗셈, %)

  // ── L47~48 : 저체력 취소 ────────────────────────────────
  if hp_ratio < 41 {
      self.chats.push(Chat::Cancel(CancelReason::LowHpSelf));  // tag 17, payload byte 0
      self.phase = LineGankerPhase::Cancel;                    // +0x29 = 8
      return;                                                  // L62
  }

  // ── L54 : 목표 부시 산출 (target_bush_v30 이 통째로 인라인) ─
  let bush = self.target_bush_v30(player, data);   // 아래 별도 서술

  // ── L55 : 챔프가 지금 서 있는 칸의 부시 id ───────────────
  let gy = clamp(champ.y / 32000, 0, 29);      // +0x668
  let gx = clamp(champ.x / 32000, 0, 29);      // +0x660
  let champ_bush = data.context.map.bushes[gy][gx];   // MapDef+0x1c98, [30][30] i64

  // ── L56~58 : 도착했는데 칠 대상이 없으면 취소 ─────────────
  if champ_bush == bush {
      if !goal_data.has_near_line_enemy(self.line, data.context.map) {   // L57
          self.chats.push(Chat::Cancel(CancelReason::TargetMissing));    // L58, tag 17, payload 2
          self.phase = LineGankerPhase::Cancel;                          // +0x29 = 8
      }
  }
  // champ_bush != bush 이면 아무 것도 안 한다(= 계속 이동 중). L62 ret.
}

// ══ 인라인된 self.target_bush_v30(player, data) — ganker.rs:248~305 ══
// 반환 = 부시 id(usize). team 은 위와 같은 player.info.team.
fn target_bush_v30(&self, player, data) -> usize {
  // L249: tower(line, team) = cache.<line>_tower[team].or(cache.<line>_tower2[team])
  //       gep: 384 + line*32 + team*8   /   400 + line*32 + team*8
  //       (top_tower 0x180, top_tower2 0x190, mid_tower 0x1a0, ... bottom_tower2 0x1d0)
  let tower = tower1.or(tower2);

  // L250~254: 그 라인의 1·2차탑이 둘 다 없으면 라인별·팀별 고정 부시
  if tower.is_none() {
      return match self.line {
          Top    => if team == 0 { 2 } else { 16 },   // L252
          Mid    => if team == 0 { 4 } else { 17 },   // L253
          Bottom => if team == 0 { 9 } else { 21 },   // L254
      };
  }
  let tower = tower.unwrap();          // L258
  let champ = <위와 동일한 champ>;      // L259 (CSE 되어 같은 포인터)

  match self.line {                    // L261 switch

    // ── Top (L262~275) ───────────────────────────────────
    Top => {
      if let EntityType::Tower(info) = &tower.ty {   // L263, 판별자 +0x68 == 2
          if tower.ty.is_tower2() { return if team==0 {3} else {6}; }  // L264~265, TowerType(+0x128) > 4
          if info.nearest_enemy.is_some() {                            // L267, +0x88 판별자 != 0
              return if team==0 {6} else {3};                          // L268  ← 팀 뒤집힘
          } else {
              return if team==0 {3} else {6};                          // L270
          }
      }
      unreachable!();                  // L274 (Tower 가 아니면 패닉)
    }

    // ── Mid (L278~286) ───────────────────────────────────
    Mid => {
      if tower.ty.is_tower2() {                       // L278 = (판별자==2) && (TowerType > 4)
          // L279 is_top_side(context, champ.x, champ.y)
          //   = { let ry = context.setting.height - champ.y; ry < champ.x }   (map_regions.rs:22~24)
          if is_top_side(..) { return if team==0 {13} else {18}; }  // L282
          else               { return if team==0 { 8} else {12}; }  // L280
      } else {                                        // 탑이 없는 게 아니라 "2차탑이 아님"
          // L285 — ★이 분기만 team 을 전혀 안 본다
          if is_top_side(..) { return 14; } else { return 11; }
      }
    }

    // ── Bottom (L293~305) ────────────────────────────────
    Bottom => {
      if let EntityType::Tower(info) = &tower.ty {    // L293
          if tower.ty.is_tower2() { return if team==0 {15} else {20}; }  // L294~295
          if info.nearest_enemy.is_some() {                              // L297
              return if team==0 {20} else {15};                          // L298  ← 팀 뒤집힘
          } else {
              return if team==0 {15} else {20};                          // L300
          }
      }
      unreachable!();                  // L304
    }
  }
}

// ── 관측된 IR 사실 몇 가지 ────────────────────────────────
// * Top/Bottom 의 세 반환 조합은 {3,6}·{15,20} 두 값의 팀 배치만 바꾼다.
//   nearest_enemy=Some(= 탑이 적에게 물려 있음)일 때만 반대쪽 부시로 뒤집힌다.
// * 두 push 경로의 `phase = 8` 저장은 컴파일러가 하나로 tail-merge 했다(블록 %182,
